    ,p_stmt_num => 32
 ,p_stmt_text => 
'CREATE OR REPLACE VIEW V_SUIVI_CONTRATS AS '||wwv_flow.LF||
'SELECT  '||wwv_flow.LF||
'    SC.*, '||wwv_flow.LF||
'    -- Calculs de délais en jours '||wwv_flow.LF||
'    ROUND((NVL(DATE_AVIS_JURIDIQUE, SYSDATE) - DATE_LIVRAISON_JURIDIQUE), 1) AS DELAI_JURIDIQUE_JOURS, '||wwv_flow.LF||
'    ROUND((NVL(DATE_GARANTIE_FINALE, SYSDATE) - DATE_LIVRAISON_JURIDIQUE), 1) AS DUREE_TOTALE_JOURS, '||wwv_flow.LF||
'    -- Statut intelligent '||wwv_flow.LF||
'    CASE  '||wwv_flow.LF||
'        WHEN DATE_GARANTIE_FINALE IS NOT NULL THEN ''✅ TER'||
'MINÉ'' '||wwv_flow.LF||
'        WHEN DATE_RETOUR_ENREGISTRE IS NOT NULL THEN ''⏳ ATTENTE GARANTIE'' '||wwv_flow.LF||
'        WHEN DATE_RETOUR_ADMIN_SIGNE IS NOT NULL THEN ''📝 ENREGISTREMENT'' '||wwv_flow.LF||
'        WHEN DATE_RETOUR_CLIENT_SIGNE IS NOT NULL THEN ''👨 ADMINISTRATION'' '||wwv_flow.LF||
'        ELSE ''🚀 EN COURS'' '||wwv_flow.LF||
'    END AS STATUT, '||wwv_flow.LF||
'    -- Dernière action '||wwv_flow.LF||
'    COALESCE( '||wwv_flow.LF||
'        TO_CHAR(DATE_GARANTIE_FINALE, ''DD/MM HH24:MI''), '||wwv_flow.LF||
'        TO_CHAR(DATE_RETOU'||
'R_ENREGISTRE, ''DD/MM HH24:MI''), '||wwv_flow.LF||
'        TO_CHAR(DATE_RETOUR_ADMIN_SIGNE, ''DD/MM HH24:MI''), '||wwv_flow.LF||
'        TO_CHAR(SYSDATE, ''DD/MM HH24:MI'') '||wwv_flow.LF||
'    ) AS DERNIERE_ACTION '||wwv_flow.LF||
'FROM SUIVI_CONTRATS '
    ,p_result_size => null
    ,p_result_rows => null
    ,p_msg => 'Erreur à la ligne 3/8 : ORA-00904: "SC" : identificateur non valide'
    ,p_success => 'N'
