  wwv_imp_workspace.create_sw_detail_results (
    p_id => 4476479885506793
    ,p_result_id => 4474103404506760
    ,p_file_id => 4401221262506190
    ,p_seq_id => 23
    ,p_stmt_num => 65
 ,p_stmt_text => 
'  CREATE OR REPLACE EDITIONABLE TRIGGER "BIU_EBA_DEMO_TREE_POP"  '||wwv_flow.LF||
'   before insert or update on eba_demo_tree_population '||wwv_flow.LF||
'   for each row '||wwv_flow.LF||
'begin   '||wwv_flow.LF||
'   if :new."ID" is null then '||wwv_flow.LF||
'     select to_number(sys_guid(),''XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX'') into :new.id from dual; '||wwv_flow.LF||
'   end if; '||wwv_flow.LF||
'   if inserting then '||wwv_flow.LF||
'       :new.created := current_timestamp; '||wwv_flow.LF||
'       :new.created_by := nvl(wwv_flow.g_user,user)'||
'; '||wwv_flow.LF||
'       :new.updated := current_timestamp; '||wwv_flow.LF||
'       :new.updated_by := nvl(wwv_flow.g_user,user); '||wwv_flow.LF||
'   end if; '||wwv_flow.LF||
