begin
  wwv_imp_workspace.create_sw_detail_results (
    p_id => 16252136658991492
    ,p_result_id => 16242315343991398
    ,p_file_id => 15200177610944170
    ,p_seq_id => 98
    ,p_stmt_num => 600
 ,p_stmt_text => 
'create or replace TRIGGER TRG_AUDIT_CC '||wwv_flow.LF||
'AFTER INSERT OR UPDATE OR DELETE ON CC '||wwv_flow.LF||
'FOR EACH ROW '||wwv_flow.LF||
'DECLARE '||wwv_flow.LF||
'    v_action VARCHAR2(10); '||wwv_flow.LF||
'    v_record_id VARCHAR2(100); '||wwv_flow.LF||
'    v_old_clob CLOB := ''{''; -- On ouvre l''accolade tout de suite '||wwv_flow.LF||
'    v_new_clob CLOB := ''{''; '||wwv_flow.LF||
'    v_user_audit VARCHAR2(100); '||wwv_flow.LF||
'    v_comma VARCHAR2(2) := ''''; -- Sert à gérer la virgule entre les champs '||wwv_flow.LF||
'     '||wwv_flow.LF||
'    -- Fonction locale pour'||
' échapper les guillemets '||wwv_flow.LF||
'    FUNCTION SAFE_TXT(p_input VARCHAR2) RETURN VARCHAR2 IS '||wwv_flow.LF||
'    BEGIN '||wwv_flow.LF||
'        RETURN REPLACE(p_input, ''"'', ''\"''); '||wwv_flow.LF||
'    END; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Procédure locale pour comparer et ajouter si changé '||wwv_flow.LF||
'    PROCEDURE CHECK_CHANGE(p_col_name VARCHAR2, p_old_val VARCHAR2, p_new_val VARCHAR2) IS '||wwv_flow.LF||
'    BEGIN '||wwv_flow.LF||
'        -- On compare les valeurs (en gérant les NULLs correctement) '||wwv_flow.LF||
'        IF (p'||
'_old_val <> p_new_val)  '||wwv_flow.LF||
'           OR (p_old_val IS NULL AND p_new_val IS NOT NULL)  '||wwv_flow.LF||
'           OR (p_old_val IS NOT NULL AND p_new_val IS NULL) THEN '||wwv_flow.LF||
'            '||wwv_flow.LF||
'            -- Ajout à l''ancien JSON '||wwv_flow.LF||
'            v_old_clob := v_old_clob || v_comma || ''"'' || p_col_name || ''": "'' || SAFE_TXT(p_old_val) || ''"''; '||wwv_flow.LF||
'            -- Ajout au nouveau JSON '||wwv_flow.LF||
'            v_new_clob := v_new_clob || v_comma'||
' || ''"'' || p_col_name || ''": "'' || SAFE_TXT(p_new_val) || ''"''; '||wwv_flow.LF||
'             '||wwv_flow.LF||
'            -- Après le premier ajout, le séparateur devient une virgule '||wwv_flow.LF||
'            v_comma := '', '';  '||wwv_flow.LF||
'        END IF; '||wwv_flow.LF||
'    END; '||wwv_flow.LF||
' '||wwv_flow.LF||
'BEGIN '||wwv_flow.LF||
'    -- 0. RECUPERATION UTILISATEUR '||wwv_flow.LF||
'    v_user_audit := COALESCE(V(''P0_USER''), USER); '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- 1. INITIALISATION '||wwv_flow.LF||
'    IF INSERTING THEN '||wwv_flow.LF||
'        v_action := ''INSERT''; '||wwv_flow.LF||
'        v_re'||
'cord_id := :NEW.ID; '||wwv_flow.LF||
'    ELSIF UPDATING THEN '||wwv_flow.LF||
'        v_action := ''UPDATE''; '||wwv_flow.LF||
'        v_record_id := :NEW.ID; '||wwv_flow.LF||
'    ELSIF DELETING THEN '||wwv_flow.LF||
'        v_action := ''DELETE''; '||wwv_flow.LF||
'        v_record_id := :OLD.ID; '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- 2. TRAITEMENT SELON L''ACTION '||wwv_flow.LF||
'     '||wwv_flow.LF||
'    ------------------------------------------------------- '||wwv_flow.LF||
'    -- CAS UPDATE : ON NE GARDE QUE CE QUI CHANGE '||wwv_flow.LF||
'    ---------------------------'||
'---------------------------- '||wwv_flow.LF||
'    IF UPDATING THEN '||wwv_flow.LF||
'        -- On appelle la procédure pour chaque champ (Code plus propre) '||wwv_flow.LF||
'        -- Note : On convertit tout en CHAR pour la comparaison simplifiée '||wwv_flow.LF||
'         '||wwv_flow.LF||
'        CHECK_CHANGE(''REF_AO'', :OLD.REF_AO, :NEW.REF_AO); '||wwv_flow.LF||
'        CHECK_CHANGE(''OBJET_CCT'', :OLD.OBJET_CCT, :NEW.OBJET_CCT); '||wwv_flow.LF||
'        CHECK_CHANGE(''APPROBATION'', :OLD.APPROBATION, :NEW.APP'||
'ROBATION); '||wwv_flow.LF||
'        CHECK_CHANGE(''BUDGET'', TO_CHAR(:OLD.BUDGET), TO_CHAR(:NEW.BUDGET)); '||wwv_flow.LF||
'        CHECK_CHANGE(''DÉTAIL_DE_RÉPONSE'', :OLD.DÉTAIL_DE_RÉPONSE, :NEW.DÉTAIL_DE_RÉPONSE); '||wwv_flow.LF||
'        CHECK_CHANGE(''NATURE_DE_DEPENSE'', :OLD.NATURE_DE_DEPENSE, :NEW.NATURE_DE_DEPENSE); '||wwv_flow.LF||
'         '||wwv_flow.LF||
'        -- Pour les dates, on compare les chaînes formatées '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_LIMITE_PROPOSÉE'', TO_CHAR(:OL'||
'D.DATE_LIMITE_PROPOSÉE, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_LIMITE_PROPOSÉE, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_DE_LANC'', TO_CHAR(:OLD.DATE_DE_LANC, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_DE_LANC, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'         '||wwv_flow.LF||
'        CHECK_CHANGE(''PV_CCT'', :OLD.PV_CCT, :NEW.PV_CCT); '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_PV'', TO_CHAR(:OLD.DATE_PV, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_PV, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'        C'||
'HECK_CHANGE(''ACCORD_DG'', :OLD.ACCORD_DG, :NEW.ACCORD_DG); '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_ACCORD'', TO_CHAR(:OLD.DATE_ACCORD, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_ACCORD, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'        CHECK_CHANGE(''PROPOSITION_DC'', :OLD.PROPOSITION_DC_ET_DÉSIGNATION, :NEW.PROPOSITION_DC_ET_DÉSIGNATION); '||wwv_flow.LF||
'        CHECK_CHANGE(''AVIS_DE_PRESSE'', :OLD.AVIS_DE_PRESSE, :NEW.AVIS_DE_PRESSE); '||wwv_flow.LF||
'        CHECK_CHANGE(''DAT'||
'E_PRO'', TO_CHAR(:OLD.DATE_PRO, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_PRO, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'        CHECK_CHANGE(''FAX_PRESTATAIRE'', :OLD.FAX_PRESTATAIRE, :NEW.FAX_PRESTATAIRE); '||wwv_flow.LF||
'        CHECK_CHANGE(''PROG_OUVERTURE'', :OLD.PROGRAMME_OUVERTURE_DE_PLIS, :NEW.PROGRAMME_OUVERTURE_DE_PLIS); '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_AVIS'', TO_CHAR(:OLD.DATE_AVIS, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_AVIS, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'     '||
'   CHECK_CHANGE(''CRITÈRES'', :OLD.CRITÈRES, :NEW.CRITÈRES); '||wwv_flow.LF||
'        CHECK_CHANGE(''NOTE_OUVERTURE_PLIS'', :OLD.NOTE_OUVERTURE_PLIS, :NEW.NOTE_OUVERTURE_PLIS); '||wwv_flow.LF||
'        CHECK_CHANGE(''JOURS_REST'', TO_CHAR(:OLD.JOURS_REST), TO_CHAR(:NEW.JOURS_REST)); '||wwv_flow.LF||
'        CHECK_CHANGE(''DATE_OUVERTURE'', TO_CHAR(:OLD.DATE_OUVERTURE_DES_PLIS, ''YYYY-MM-DD''), TO_CHAR(:NEW.DATE_OUVERTURE_DES_PLIS, ''YYYY-MM-DD'')); '||wwv_flow.LF||
'      '||
'  CHECK_CHANGE(''STATUS'', :OLD.STATUS, :NEW.STATUS); '||wwv_flow.LF||
'         '||wwv_flow.LF||
'        -- Si v_comma est vide, c''est qu''aucune modification n''a été détectée '||wwv_flow.LF||
'        -- Optionnel : on peut décider de ne rien insérer si rien n''a changé '||wwv_flow.LF||
'        IF v_comma = '''' THEN '||wwv_flow.LF||
'            RETURN; -- On arrête tout, pas d''insertion dans les logs '||wwv_flow.LF||
'        END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    ------------------------------------------------------- '||wwv_flow.LF||
''||
'    -- CAS INSERT / DELETE : ON GARDE TOUT (Snapshot) '||wwv_flow.LF||
'    ------------------------------------------------------- '||wwv_flow.LF||
'    ELSE '||wwv_flow.LF||
'        -- Pour simplifier, je remets la construction manuelle ici pour Insert/Delete '||wwv_flow.LF||
'        -- car CHECK_CHANGE compare old/new, or ici l''un des deux est vide. '||wwv_flow.LF||
'         '||wwv_flow.LF||
'        -- Astuce : Pour INSERT, on boucle sur NEW. Pour DELETE, sur OLD. '||wwv_flow.LF||
'        DECLARE '||wwv_flow.LF||
'        '||
'    -- On utilise des pointeurs pour éviter de dupliquer le code '||wwv_flow.LF||
'            v_ref_ao VARCHAR2(4000); v_objet VARCHAR2(4000); -- etc... '||wwv_flow.LF||
'            -- Simplification : On construit le bloc directement '||wwv_flow.LF||
'        BEGIN '||wwv_flow.LF||
'             -- (Pour garder le code lisible ici, je réutilise la méthode concaténation directe du code précédent '||wwv_flow.LF||
'             -- mais adaptée pour remplir v_new_clob OU v_old_clob'||
' selon le cas) '||wwv_flow.LF||
'              '||wwv_flow.LF||
'             IF INSERTING THEN '||wwv_flow.LF||
'                 v_new_clob := ''{'' ||  '||wwv_flow.LF||
'                    ''"ID": "'' || :NEW.ID || ''", '' || '||wwv_flow.LF||
'                    ''"REF_AO": "'' || SAFE_TXT(:NEW.REF_AO) || ''", '' || '||wwv_flow.LF||
'                    ''"OBJET_CCT": "'' || SAFE_TXT(:NEW.OBJET_CCT) || ''", '' || '||wwv_flow.LF||
'                    ''"STATUS": "'' || SAFE_TXT(:NEW.STATUS) || ''", '' || '||wwv_flow.LF||
'                    -'||
'- ... (Ajoutez ici les autres champs si vous voulez le snapshot complet à la création) '||wwv_flow.LF||
'                    ''"CREER_PAR": "'' || SAFE_TXT(:NEW.CREER_PAR) || ''"''; -- Pas de virgule à la fin '||wwv_flow.LF||
'             ELSIF DELETING THEN '||wwv_flow.LF||
'                 v_old_clob := ''{'' ||  '||wwv_flow.LF||
'                    ''"ID": "'' || :OLD.ID || ''", '' || '||wwv_flow.LF||
'                    ''"REF_AO": "'' || SAFE_TXT(:OLD.REF_AO) || ''", '' || '||wwv_flow.LF||
'           '||
'         ''"OBJET_CCT": "'' || SAFE_TXT(:OLD.OBJET_CCT) || ''", '' || '||wwv_flow.LF||
'                    ''"STATUS": "'' || SAFE_TXT(:OLD.STATUS) || ''"'';  '||wwv_flow.LF||
'             END IF; '||wwv_flow.LF||
'        END; '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Fermeture du JSON '||wwv_flow.LF||
'    v_old_clob := v_old_clob || ''}''; '||wwv_flow.LF||
'    v_new_clob := v_new_clob || ''}''; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- 3. INSERTION FINALE '||wwv_flow.LF||
'    INSERT INTO AUDIT_LOG ( '||wwv_flow.LF||
'        TABLE_NAME, ACTION_TYPE, RECORD_ID, OLD_VALU'||
'E, NEW_VALUE, CHANGED_BY '||wwv_flow.LF||
'    ) VALUES ( '||wwv_flow.LF||
'        ''CC'', v_action, v_record_id, v_old_clob, v_new_clob, v_user_audit '||wwv_flow.LF||
'    ); '||wwv_flow.LF||
' '||wwv_flow.LF||
'END; '
    ,p_result_size => 0
    ,p_result_rows => 0
    ,p_msg => 'Trigger created.'
    ,p_success => 'Y'
    ,p_failure => 'N'
    ,p_started => to_date('202512031556','YYYYMMDDHH24MI')
    ,p_start_time => 71991492
    ,p_ended => to_date('202512031556','YYYYMMDDHH24MI')
    ,p_end_time => 71991495
    ,p_run_complete => 'Y'
    ,p_last_updated => to_date('202512031556','YYYYMMDDHH24MI'));
end;
