 ,p_stmt_text => 
'CREATE OR REPLACE PROCEDURE migrate_passwords IS '||wwv_flow.LF||
'    l_salt VARCHAR2(100); '||wwv_flow.LF||
'    l_hash VARCHAR2(255); '||wwv_flow.LF||
'BEGIN '||wwv_flow.LF||
'    FOR rec IN (SELECT ID, MATRICULE, NOM, MDP, GROUPE FROM SP) LOOP '||wwv_flow.LF||
'        l_salt := generate_salt(); '||wwv_flow.LF||
'        l_hash := hash_password(rec.MDP, l_salt); '||wwv_flow.LF||
' '||wwv_flow.LF||
'        INSERT INTO SP_SECURE (ID, MATRICULE, NOM, MDP_HASH, MDP_SALT, GROUPE) '||wwv_flow.LF||
'        VALUES (rec.ID, rec.MATRICULE, rec.NOM, l_'||
'hash, l_salt, rec.GROUPE); '||wwv_flow.LF||
