' '||wwv_flow.LF||
'    -- Identification '||wwv_flow.LF||
'    N_FACTURE           VARCHAR2(100)  NOT NULL ENABLE, '||wwv_flow.LF||
'    DATE_FACTURE  '||
'      DATE, '||wwv_flow.LF||
'    DATE_RECEPTION      DATE, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Montants '||wwv_flow.LF||
'    MONTANT_HT          NUMBER(18,3), '||wwv_flow.LF||
'    MONTANT_TVA         NUMBER(18,3), '||wwv_flow.LF||
'    MONTANT_TTC         NUMBER(18,3), '||wwv_flow.LF||
'    DEVISE              VARCHAR2(10)   DEFAULT ''TND'', '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Validation interne '||wwv_flow.LF||
'    DATE_VALIDATION     DATE, '||wwv_flow.LF||
'    VALIDEE_PAR         VARCHAR2(100), '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Paiement '||wwv_flow.LF||
'    DATE_PAIEMENT       DATE, '||wwv_flow.LF||
'    REF_VIREMEN'||
'T        VARCHAR2(100), '||wwv_flow.LF||
'    BANQUE              VARCHAR2(150), '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Statut & suivi '||wwv_flow.LF||
'    STATUT              VARCHAR2(50)   DEFAULT ''Reçue'', '||wwv_flow.LF||
'    MOTIF_REJET         VARCHAR2(500), '||wwv_flow.LF||
