begin
  wwv_imp_workspace.create_sw_detail_results (
    p_id => 34479331942668526
    ,p_result_id => 34478027693668504
    ,p_file_id => 34425703828668304
    ,p_seq_id => 13
    ,p_stmt_num => 58
 ,p_stmt_text => 
'CREATE OR REPLACE TRIGGER FACTURES_T '||wwv_flow.LF||
'BEFORE INSERT OR UPDATE ON FACTURES '||wwv_flow.LF||
'FOR EACH ROW '||wwv_flow.LF||
'BEGIN '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- a) Calcul automatique MONTANT_TTC '||wwv_flow.LF||
'    IF :NEW.MONTANT_TTC IS NULL '||wwv_flow.LF||
'       AND :NEW.MONTANT_HT IS NOT NULL '||wwv_flow.LF||
'    THEN '||wwv_flow.LF||
'        :NEW.MONTANT_TTC := :NEW.MONTANT_HT + NVL(:NEW.MONTANT_TVA, 0); '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- a) Calcul automatique MONTANT_TVA (si HT et TTC connus mais pas TVA) '||wwv_flow.LF||
'    IF :NEW.'||
'MONTANT_TVA IS NULL '||wwv_flow.LF||
'       AND :NEW.MONTANT_HT  IS NOT NULL '||wwv_flow.LF||
'       AND :NEW.MONTANT_TTC IS NOT NULL '||wwv_flow.LF||
'    THEN '||wwv_flow.LF||
'        :NEW.MONTANT_TVA := :NEW.MONTANT_TTC - :NEW.MONTANT_HT; '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- b) Statut "Payée" : dès qu''une date de paiement est saisie '||wwv_flow.LF||
'    IF :NEW.DATE_PAIEMENT IS NOT NULL '||wwv_flow.LF||
'       AND NVL(:NEW.STATUT, ''Reçue'') != ''Rejetée'' '||wwv_flow.LF||
'    THEN '||wwv_flow.LF||
'        :NEW.STATUT := ''Payée''; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -'||
'- b) Statut "Validée" : date de validation saisie, pas encore payée '||wwv_flow.LF||
'    ELSIF :NEW.DATE_VALIDATION IS NOT NULL '||wwv_flow.LF||
'       AND :NEW.DATE_PAIEMENT IS NULL '||wwv_flow.LF||
'       AND NVL(:NEW.STATUT, ''Reçue'') NOT IN (''Rejetée'', ''Payée'') '||wwv_flow.LF||
'    THEN '||wwv_flow.LF||
'        :NEW.STATUT := ''Validée''; '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- c) Horodatage '||wwv_flow.LF||
'    :NEW.DATE_MAJ := SYSDATE; '||wwv_flow.LF||
'    :NEW.MAJ_PAR  := NVL( '||wwv_flow.LF||
'        SYS_CONTEXT(''APEX$SESSION'',''APP_US'||
'ER''), '||wwv_flow.LF||
'        SYS_CONTEXT(''USERENV'',''SESSION_USER'') '||wwv_flow.LF||
'    ); '||wwv_flow.LF||
' '||wwv_flow.LF||
'END; '
    ,p_result_size => 0
    ,p_result_rows => 0
    ,p_msg => 'Trigger created.'
    ,p_success => 'Y'
    ,p_failure => 'N'
    ,p_started => to_date('202604201022','YYYYMMDDHH24MI')
    ,p_start_time => 33668526
