begin
  wwv_imp_workspace.create_sw_detail_results (
    p_id => 34479577179668531
    ,p_result_id => 34478027693668504
    ,p_file_id => 34425703828668304
    ,p_seq_id => 15
    ,p_stmt_num => 72
 ,p_stmt_text => 
'CREATE OR REPLACE VIEW V_FACTURES AS '||wwv_flow.LF||
'SELECT '||wwv_flow.LF||
'    f.ID, '||wwv_flow.LF||
'    f.ID_CONTRAT, '||wwv_flow.LF||
'    c.N_CONTRAT_BC, '||wwv_flow.LF||
'    c.TITULAIRE_DU_MARCHÉ, '||wwv_flow.LF||
'    c.OBJET                                     AS OBJET_CONTRAT, '||wwv_flow.LF||
'    c.MONTANT                                   AS MONTANT_CONTRAT, '||wwv_flow.LF||
'    c.ETAT                                      AS ETAT_CONTRAT, '||wwv_flow.LF||
'    c.RESPONSABLE, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Identification facture '||wwv_flow.LF||
'    f.N_FACTURE, '||wwv_flow.LF||
'  '||
'  f.DATE_FACTURE, '||wwv_flow.LF||
'    f.DATE_RECEPTION, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Montants '||wwv_flow.LF||
'    f.MONTANT_HT, '||wwv_flow.LF||
'    f.MONTANT_TVA, '||wwv_flow.LF||
'    f.MONTANT_TTC, '||wwv_flow.LF||
'    f.DEVISE, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Validation '||wwv_flow.LF||
'    f.DATE_VALIDATION, '||wwv_flow.LF||
'    f.VALIDEE_PAR, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Paiement '||wwv_flow.LF||
'    f.DATE_PAIEMENT, '||wwv_flow.LF||
'    f.REF_VIREMENT, '||wwv_flow.LF||
'    f.BANQUE, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Statut '||wwv_flow.LF||
'    f.STATUT, '||wwv_flow.LF||
'    f.MOTIF_REJET, '||wwv_flow.LF||
'    f.OBSERVATION, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Calcul retard : nb jours depuis validation'||
' sans paiement '||wwv_flow.LF||
'    CASE '||wwv_flow.LF||
'        WHEN f.STATUT IN (''Validée'', ''En attente validation'') '||wwv_flow.LF||
'             AND f.DATE_VALIDATION IS NOT NULL '||wwv_flow.LF||
'             AND f.DATE_PAIEMENT   IS NULL '||wwv_flow.LF||
'        THEN TRUNC(SYSDATE - f.DATE_VALIDATION) '||wwv_flow.LF||
'        ELSE NULL '||wwv_flow.LF||
'    END                                         AS JOURS_DEPUIS_VALIDATION, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Indicateur retard pour mise en forme conditionnelle APEX '||wwv_flow.LF||
'    CAS'||
'E '||wwv_flow.LF||
'        WHEN f.STATUT IN (''Validée'', ''En attente validation'') '||wwv_flow.LF||
'             AND f.DATE_VALIDATION IS NOT NULL '||wwv_flow.LF||
'             AND f.DATE_PAIEMENT   IS NULL '||wwv_flow.LF||
'             AND TRUNC(SYSDATE - f.DATE_VALIDATION) > 30 '||wwv_flow.LF||
'        THEN ''RETARD'' '||wwv_flow.LF||
'        WHEN f.STATUT IN (''Validée'', ''En attente validation'') '||wwv_flow.LF||
'             AND f.DATE_VALIDATION IS NOT NULL '||wwv_flow.LF||
'             AND f.DATE_PAIEMENT   IS NULL '||wwv_flow.LF||
'      '||
'       AND TRUNC(SYSDATE - f.DATE_VALIDATION) BETWEEN 15 AND 30 '||wwv_flow.LF||
'        THEN ''ATTENTION'' '||wwv_flow.LF||
'        ELSE ''OK'' '||wwv_flow.LF||
'    END                                         AS INDICATEUR_RETARD, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Classe CSS pour badge statut (utilisable directement dans APEX HTML Expr.) '||wwv_flow.LF||
'    CASE f.STATUT '||wwv_flow.LF||
'        WHEN ''Payée''                  THEN ''u-color-15'' '||wwv_flow.LF||
'        WHEN ''Validée''                THEN ''u-color-1'' '||wwv_flow.LF||
'  '||
'      WHEN ''En attente validation''  THEN ''u-color-8'' '||wwv_flow.LF||
'        WHEN ''Rejetée''                THEN ''u-color-9'' '||wwv_flow.LF||
'        ELSE                               ''u-color-45'' '||wwv_flow.LF||
'    END                                         AS STATUT_CSS_CLASS, '||wwv_flow.LF||
' '||wwv_flow.LF||
'    f.DATE_CREATION, '||wwv_flow.LF||
'    f.CREE_PAR, '||wwv_flow.LF||
'    f.DATE_MAJ, '||wwv_flow.LF||
'    f.MAJ_PAR '||wwv_flow.LF||
' '||wwv_flow.LF||
'FROM FACTURES f '||wwv_flow.LF||
'JOIN CONTRATS c ON c.ID = f.ID_CONTRAT'
    ,p_result_size => 0
    ,p_result_rows => 0
    ,p_msg => 'View created.'
    ,p_success => 'Y'
    ,p_failure => 'N'
    ,p_started => to_date('202604201022','YYYYMMDDHH24MI')
    ,p_start_time => 33668531
    ,p_ended => to_date('202604201022','YYYYMMDDHH24MI')
    ,p_end_time => 33668534
    ,p_run_complete => 'Y'
    ,p_last_updated => to_date('202604201022','YYYYMMDDHH24MI'));
end;
