begin
  wwv_imp_workspace.create_sw_detail_results (
    p_id => 34479730662668539
    ,p_result_id => 34478027693668504
    ,p_file_id => 34425703828668304
    ,p_seq_id => 17
    ,p_stmt_num => 102
 ,p_stmt_text => 
'CREATE OR REPLACE PROCEDURE SP_ALERTES_FACTURES AS '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Destinataire des alertes (à adapter) '||wwv_flow.LF||
'    c_email_dest    CONSTANT VARCHAR2(200) := ''gestion.contrats@votre-societe.tn''; '||wwv_flow.LF||
'    c_email_from    CONSTANT VARCHAR2(200) := ''apex-noreply@votre-societe.tn''; '||wwv_flow.LF||
'    c_seuil_alerte  CONSTANT NUMBER        := 30;   -- jours depuis validation '||wwv_flow.LF||
'    c_seuil_warning CONSTANT NUMBER        := 15; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    '||
'v_corps         CLOB; '||wwv_flow.LF||
'    v_nb_retard     NUMBER := 0; '||wwv_flow.LF||
'    v_nb_warning    NUMBER := 0; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    CURSOR c_retards IS '||wwv_flow.LF||
'        SELECT '||wwv_flow.LF||
'            N_CONTRAT_BC, '||wwv_flow.LF||
'            TITULAIRE_DU_MARCHÉ, '||wwv_flow.LF||
'            N_FACTURE, '||wwv_flow.LF||
'            TO_CHAR(DATE_VALIDATION,  ''DD/MM/YYYY'') AS DT_VALID, '||wwv_flow.LF||
'            MONTANT_TTC, '||wwv_flow.LF||
'            DEVISE, '||wwv_flow.LF||
'            JOURS_DEPUIS_VALIDATION, '||wwv_flow.LF||
'            INDICATEUR_RETARD,'||
' '||wwv_flow.LF||
'            RESPONSABLE '||wwv_flow.LF||
'        FROM V_FACTURES '||wwv_flow.LF||
'        WHERE INDICATEUR_RETARD IN (''RETARD'', ''ATTENTION'') '||wwv_flow.LF||
'          AND STATUT IN (''Validée'', ''En attente validation'') '||wwv_flow.LF||
'        ORDER BY JOURS_DEPUIS_VALIDATION DESC NULLS LAST; '||wwv_flow.LF||
' '||wwv_flow.LF||
'BEGIN '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Construction du corps HTML de l''e-mail '||wwv_flow.LF||
'    v_corps := ''<html><body style="font-family:Arial,sans-serif;font-size:13px;">'' '||wwv_flow.LF||
'            || ''<h2 style'||
'="color:#185FA5;">Alertes Factures en attente de paiement</h2>'' '||wwv_flow.LF||
'            || ''<p>Date du rapport : <b>'' || TO_CHAR(SYSDATE,''DD/MM/YYYY HH24:MI'') || ''</b></p>'' '||wwv_flow.LF||
'            || ''<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;">'' '||wwv_flow.LF||
'            || ''<thead style="background:#E6F1FB;">'' '||wwv_flow.LF||
'            || ''<tr>'' '||wwv_flow.LF||
'            || ''<th>Contrat</th><th>Titulaire<'||
'/th><th>N° Facture</th>'' '||wwv_flow.LF||
'            || ''<th>Montant TTC</th><th>Validée le</th><th>Jours écoulés</th>'' '||wwv_flow.LF||
'            || ''<th>Responsable</th><th>Niveau</th>'' '||wwv_flow.LF||
'            || ''</tr></thead><tbody>''; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    FOR r IN c_retards LOOP '||wwv_flow.LF||
' '||wwv_flow.LF||
'        IF r.INDICATEUR_RETARD = ''RETARD'' THEN '||wwv_flow.LF||
'            v_nb_retard := v_nb_retard + 1; '||wwv_flow.LF||
'        ELSE '||wwv_flow.LF||
'            v_nb_warning := v_nb_warning + 1; '||wwv_flow.LF||
'        END I'||
'F; '||wwv_flow.LF||
' '||wwv_flow.LF||
'        v_corps := v_corps '||wwv_flow.LF||
'            || ''<tr style="background:'' '||wwv_flow.LF||
'            || CASE r.INDICATEUR_RETARD '||wwv_flow.LF||
'                   WHEN ''RETARD''    THEN ''#FCEBEB'' '||wwv_flow.LF||
'                   WHEN ''ATTENTION'' THEN ''#FAEEDA'' '||wwv_flow.LF||
'                   ELSE ''#FFFFFF'' '||wwv_flow.LF||
'               END || '';">'' '||wwv_flow.LF||
'            || ''<td>'' || r.N_CONTRAT_BC         || ''</td>'' '||wwv_flow.LF||
'            || ''<td>'' || r.TITULAIRE_DU_MARCHÉ  || ''</td'||
'>'' '||wwv_flow.LF||
'            || ''<td>'' || r.N_FACTURE            || ''</td>'' '||wwv_flow.LF||
'            || ''<td style="text-align:right;">'' '||wwv_flow.LF||
'            ||     TO_CHAR(r.MONTANT_TTC, ''FM999G999G990D000'') || '' '' || r.DEVISE '||wwv_flow.LF||
'            || ''</td>'' '||wwv_flow.LF||
'            || ''<td>'' || r.DT_VALID             || ''</td>'' '||wwv_flow.LF||
'            || ''<td style="text-align:center;font-weight:bold;">'' '||wwv_flow.LF||
'            ||     r.JOURS_DEPUIS_VALIDATION || '' j'' '||
''||wwv_flow.LF||
'            || ''</td>'' '||wwv_flow.LF||
'            || ''<td>'' || NVL(r.RESPONSABLE, ''-'') || ''</td>'' '||wwv_flow.LF||
'            || ''<td style="font-weight:bold;color:'' '||wwv_flow.LF||
'            ||     CASE r.INDICATEUR_RETARD '||wwv_flow.LF||
'                       WHEN ''RETARD''    THEN ''#A32D2D'' '||wwv_flow.LF||
'                       WHEN ''ATTENTION'' THEN ''#BA7517'' '||wwv_flow.LF||
'                   END || '';">'' '||wwv_flow.LF||
'            ||     r.INDICATEUR_RETARD '||wwv_flow.LF||
'            || ''</td>'' '||wwv_flow.LF||
'       '||
'     || ''</tr>''; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    END LOOP; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    v_corps := v_corps '||wwv_flow.LF||
'            || ''</tbody></table>'' '||wwv_flow.LF||
'            || ''<p style="margin-top:16px;">'' '||wwv_flow.LF||
'            || ''<b>'' || v_nb_retard  || ''</b> facture(s) en <span style="color:#A32D2D;">RETARD</span> (&gt;'' '||wwv_flow.LF||
'            || c_seuil_alerte || '' j) &nbsp;|&nbsp; '' '||wwv_flow.LF||
'            || ''<b>'' || v_nb_warning || ''</b> facture(s) en <span style="color:#BA7517;">AT'||
'TENTION</span> ('' '||wwv_flow.LF||
'            || c_seuil_warning || ''-'' || c_seuil_alerte || '' j)'' '||wwv_flow.LF||
'            || ''</p>'' '||wwv_flow.LF||
'            || ''</body></html>''; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    -- Envoi uniquement s''il y a des factures en retard ou en attention '||wwv_flow.LF||
'    IF v_nb_retard + v_nb_warning > 0 THEN '||wwv_flow.LF||
'        APEX_MAIL.SEND( '||wwv_flow.LF||
'            p_to        => c_email_dest, '||wwv_flow.LF||
'            p_from      => c_email_from, '||wwv_flow.LF||
'            p_subj      => ''[C'||
'ONTRATS] '' || (v_nb_retard + v_nb_warning) '||wwv_flow.LF||
'                           || '' facture(s) en attente de paiement — '' '||wwv_flow.LF||
'                           || TO_CHAR(SYSDATE,''DD/MM/YYYY''), '||wwv_flow.LF||
'            p_body      => ''Veuillez consulter la version HTML de cet e-mail.'', '||wwv_flow.LF||
'            p_body_html => v_corps '||wwv_flow.LF||
'        ); '||wwv_flow.LF||
'        APEX_MAIL.PUSH_QUEUE; '||wwv_flow.LF||
'    END IF; '||wwv_flow.LF||
' '||wwv_flow.LF||
'    DBMS_OUTPUT.PUT_LINE( '||wwv_flow.LF||
'        ''Alertes envo'||
'yées : '' || v_nb_retard || '' retard(s), '' '||wwv_flow.LF||
'        || v_nb_warning || '' attention(s).'' '||wwv_flow.LF||
'    ); '||wwv_flow.LF||
