    p_id => 47655951090030368045
 ,p_command => 
'CREATE OR REPLACE TRIGGER  "CC_T1" '||wwv_flow.LF||
'BEFORE'||wwv_flow.LF||
'insert or update on "CC"'||wwv_flow.LF||
'for each row'||wwv_flow.LF||
'begin'||wwv_flow.LF||
'if inserting then '||wwv_flow.LF||
'      select min(codreg) into :new.codreg from region;'||wwv_flow.LF||
'      select nvl(max(ID),0)+1 into :new.ID from CC;    '||wwv_flow.LF||
'      :new.datecr:= sysdate;'||wwv_flow.LF||
'elsif updating then'||wwv_flow.LF||
'    :new.datemj := sysdate;'||wwv_flow.LF||
'end if;'||wwv_flow.LF||
''||wwv_flow.LF||
':NEW.nomusr := nvl(v(''APP_USER''),USER);'||wwv_flow.LF||
'end;'||wwv_flow.LF||
''||wwv_flow.LF||
''||wwv_flow.LF||
''
