begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 55097388324402269057
 ,p_command => 
'create or replace view "MODIFICATION" as'||wwv_flow.LF||
'select SUIVI_MODIF.ID_MODIF as ID_MODIF,'||wwv_flow.LF||
'    SUIVI_MODIF.ID_OBJET as ID_OBJET,'||wwv_flow.LF||
'    SUIVI_MODIF.MODIFIER_PAR as MODIFIER_PAR,'||wwv_flow.LF||
'    SUIVI_MODIF.DATE_MODIF as DATE_MODIF,'||wwv_flow.LF||
'    CC.ID as ID,'||wwv_flow.LF||
'    CC.REF_AO as REF_AO,'||wwv_flow.LF||
'    upper(CC.CREER_PAR) as CREER_PAR,'||wwv_flow.LF||
'    CC."DATE_CRÉATION" as "DATE_CRÉATION" '||wwv_flow.LF||
' from CC CC,'||wwv_flow.LF||
'    SUIVI_MODIF SUIVI_MODIF '||wwv_flow.LF||
' where SUIVI_MODIF.ID_OBJET'||
'=CC.ID'||wwv_flow.LF||
'    and SUIVI_MODIF.ID_OBJET  =  CC.ID'||wwv_flow.LF||
'/   '||wwv_flow.LF||
''
    ,p_created_by => 'CHR277158@GMAIL.COM'
    ,p_created_on => to_date('202209291109','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
