begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 18011624301159031
 ,p_command => 
'CREATE OR REPLACE PROCEDURE PROCESS_REMINDERS_TO_SEND AS'||wwv_flow.LF||
'    -- تعريف الوقت الحالي مطروحاً منه فترة ما قبل التنبيه'||wwv_flow.LF||
'    -- يمثل أقصى وقت يجب أن يحدث فيه التنبيه الآن'||wwv_flow.LF||
'    v_target_time DATE := SYSDATE;'||wwv_flow.LF||
''||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- 1. تحديد وتحديث الملاحظات التي يجب تنبيه المستخدم بها الآن'||wwv_flow.LF||
'    -- ملاحظة: نحن نستخدم ''IS_SENT'' بدلاً من ''IS_ACTIVE''.'||wwv_flow.LF||
'    -- ''IS_SENT'' تمنع إرسال التنبيه لنفس الملاحظة مرة أخرى.'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    '||
'UPDATE USER_NOTES n'||wwv_flow.LF||
'    SET n.IS_SENT = ''Y'''||wwv_flow.LF||
'    WHERE n.IS_SENT = ''N'''||wwv_flow.LF||
'      -- حساب الوقت الفعلي المطلوب للتنبيه بناءً على وقت التذكير الأصلي و فترة ما قبل التنبيه'||wwv_flow.LF||
'      -- REMINDER_DATETIME - (PRE_REMINDER_MINS / (24*60))'||wwv_flow.LF||
'      AND n.REMINDER_DATETIME - (n.PRE_REMINDER_MINS / 1440) <= v_target_time'||wwv_flow.LF||
'      -- لا نريد تنبيهات فات وقتها كثيراً (نحن نهتم بالتنبيهات اللحظية أو المستقبل القريب جداً)'||wwv_flow.LF||
'   '||
'   AND n.REMINDER_DATETIME >= v_target_time - (1/1440); -- التنبيهات التي يجب إرسالها خلال الدقيقة الماضية فقط'||wwv_flow.LF||
''||wwv_flow.LF||
'    COMMIT;'||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN OTHERS THEN'||wwv_flow.LF||
'        -- يمكنك إضافة منطق تسجيل الأخطاء هنا'||wwv_flow.LF||
'        ROLLBACK;'||wwv_flow.LF||
'        RAISE;'||wwv_flow.LF||
'END PROCESS_REMINDERS_TO_SEND;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202512220955','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
