begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 14772540619510365
 ,p_command => 
'CREATE OR REPLACE PACKAGE PKG_PERPLEXITY_AI AS'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    FUNCTION call_perplexity('||wwv_flow.LF||
'        p_prompt IN CLOB,'||wwv_flow.LF||
'        p_model IN VARCHAR2 DEFAULT ''sonar-pro'''||wwv_flow.LF||
'    ) RETURN CLOB;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    FUNCTION analyser_appel_offres('||wwv_flow.LF||
'        p_refao IN VARCHAR2,'||wwv_flow.LF||
'        p_description IN CLOB'||wwv_flow.LF||
'    ) RETURN CLOB;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'END PKG_PERPLEXITY_AI;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'CREATE OR REPLACE PACKAGE BODY PKG_PERPLEXITY_AI AS'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    -- Clé API (à '||
'sécuriser dans une table ou configuration)'||wwv_flow.LF||
'    c_api_key CONSTANT VARCHAR2(100) := ''pplx-YOUR-API-KEY'';'||wwv_flow.LF||
'    c_api_url CONSTANT VARCHAR2(200) := ''https://api.perplexity.ai/chat/completions'';'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    FUNCTION call_perplexity('||wwv_flow.LF||
'        p_prompt IN CLOB,'||wwv_flow.LF||
'        p_model IN VARCHAR2 DEFAULT ''sonar-pro'''||wwv_flow.LF||
'    ) RETURN CLOB IS'||wwv_flow.LF||
'        l_response CLOB;'||wwv_flow.LF||
'        l_json_body CLOB;'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        -- Construi'||
're le JSON de requête'||wwv_flow.LF||
'        l_json_body := JSON_OBJECT('||wwv_flow.LF||
'            ''model'' VALUE p_model,'||wwv_flow.LF||
'            ''messages'' VALUE JSON_ARRAY('||wwv_flow.LF||
'                JSON_OBJECT('||wwv_flow.LF||
'                    ''role'' VALUE ''system'','||wwv_flow.LF||
'                    ''content'' VALUE ''Tu es un assistant expert en analyse d''''appels d''''offres.'''||wwv_flow.LF||
'                ),'||wwv_flow.LF||
'                JSON_OBJECT('||wwv_flow.LF||
'                    ''role'' VALUE ''user'','||wwv_flow.LF||
'         '||
'           ''content'' VALUE p_prompt'||wwv_flow.LF||
'                )'||wwv_flow.LF||
'            ),'||wwv_flow.LF||
'            ''temperature'' VALUE 0.2,'||wwv_flow.LF||
'            ''max_tokens'' VALUE 1024'||wwv_flow.LF||
'        );'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        -- Réinitialiser les headers'||wwv_flow.LF||
'        APEX_WEB_SERVICE.g_request_headers.DELETE;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        -- Ajouter les headers nécessaires'||wwv_flow.LF||
'        APEX_WEB_SERVICE.g_request_headers(1).name := ''Content-Type'';'||wwv_flow.LF||
'        APEX_WEB_SERVICE.g_r'||
'equest_headers(1).value := ''application/json'';'||wwv_flow.LF||
'        APEX_WEB_SERVICE.g_request_headers(2).name := ''Authorization'';'||wwv_flow.LF||
'        APEX_WEB_SERVICE.g_request_headers(2).value := ''Bearer '' || c_api_key;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        -- Faire l''appel API'||wwv_flow.LF||
'        l_response := APEX_WEB_SERVICE.make_rest_request('||wwv_flow.LF||
'            p_url => c_api_url,'||wwv_flow.LF||
'            p_http_method => ''POST'','||wwv_flow.LF||
'            p_body => l_json_body'||wwv_flow.LF||
'    '||
'    );'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        -- Extraire le contenu de la réponse'||wwv_flow.LF||
'        RETURN JSON_VALUE(l_response, ''$.choices[0].message.content'');'||wwv_flow.LF||
'        '||wwv_flow.LF||
'    EXCEPTION'||wwv_flow.LF||
'        WHEN OTHERS THEN'||wwv_flow.LF||
'            APEX_DEBUG.ERROR(''Erreur Perplexity API: '' || SQLERRM);'||wwv_flow.LF||
'            RETURN ''Erreur lors de l''''appel à l''''API: '' || SQLERRM;'||wwv_flow.LF||
'    END call_perplexity;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    FUNCTION analyser_appel_offres('||wwv_flow.LF||
'        p_refao IN'||
' VARCHAR2,'||wwv_flow.LF||
'        p_description IN CLOB'||wwv_flow.LF||
'    ) RETURN CLOB IS'||wwv_flow.LF||
'        l_prompt CLOB;'||wwv_flow.LF||
'        l_analyse CLOB;'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        l_prompt := ''Analyse cet appel d''''offres et fournis:'||wwv_flow.LF||
'1. Les points clés et exigences principales'||wwv_flow.LF||
'2. Les risques potentiels'||wwv_flow.LF||
'3. Les opportunités'||wwv_flow.LF||
'4. Une estimation de complexité (faible/moyenne/élevée)'||wwv_flow.LF||
'5. Des recommandations stratégiques'||wwv_flow.LF||
''||wwv_flow.LF||
'Description de l''''appel d''''offres:'||wwv_flow.LF||
''' '||
'|| p_description;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        l_analyse := call_perplexity(l_prompt, ''sonar-pro'');'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        -- Enregistrer l''analyse dans la base'||wwv_flow.LF||
'        UPDATE CC'||wwv_flow.LF||
'        SET ANALYSE_IA = l_analyse,'||wwv_flow.LF||
'            DATE_ANALYSE_IA = SYSDATE'||wwv_flow.LF||
'        WHERE REFAO = p_refao;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        COMMIT;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'        RETURN l_analyse;'||wwv_flow.LF||
'        '||wwv_flow.LF||
'    END analyser_appel_offres;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'END PKG_PERPLEXITY_AI;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202512021049','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
