'   ) ;'||wwv_flow.LF||
''||wwv_flow.LF||
'  CREATE OR REPLACE EDITIONABLE TRIGGER "TRG_AUDIT_SP" '||wwv_flow.LF||
'AF'||
'TER INSERT OR UPDATE OR DELETE ON SP'||wwv_flow.LF||
'FOR EACH ROW'||wwv_flow.LF||
'DECLARE'||wwv_flow.LF||
'    v_action VARCHAR2(10);'||wwv_flow.LF||
'    v_record_id VARCHAR2(100);'||wwv_flow.LF||
'    v_old_clob CLOB := ''{''; '||wwv_flow.LF||
'    v_new_clob CLOB := ''{'';'||wwv_flow.LF||
'    v_user_audit VARCHAR2(100);'||wwv_flow.LF||
'    v_comma VARCHAR2(2) := ''''; '||wwv_flow.LF||
'    '||wwv_flow.LF||
'    -- Fonction pour échapper les guillemets dans le texte (JSON safe)'||wwv_flow.LF||
'    FUNCTION SAFE_TXT(p_input VARCHAR2) RETURN VARCHAR2 IS'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        RETURN REP'||
'LACE(p_input, ''"'', ''\"'');'||wwv_flow.LF||
'    END;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Procédure de comparaison (Delta Log)'||wwv_flow.LF||
'    PROCEDURE CHECK_CHANGE(p_col_name VARCHAR2, p_old_val VARCHAR2, p_new_val VARCHAR2) IS'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        -- Comparaison gérant les NULLs'||wwv_flow.LF||
'        IF (p_old_val <> p_new_val) '||wwv_flow.LF||
'           OR (p_old_val IS NULL AND p_new_val IS NOT NULL) '||wwv_flow.LF||
'           OR (p_old_val IS NOT NULL AND p_new_val IS NULL) THEN'||wwv_flow.LF||
'           '||wwv_flow.LF||
'    '||
'        -- Construction du JSON (Clé : Valeur)'||wwv_flow.LF||
'            v_old_clob := v_old_clob || v_comma || ''"'' || p_col_name || ''": "'' || SAFE_TXT(p_old_val) || ''"'';'||wwv_flow.LF||
'            v_new_clob := v_new_clob || v_comma || ''"'' || p_col_name || ''": "'' || SAFE_TXT(p_new_val) || ''"'';'||wwv_flow.LF||
'            '||wwv_flow.LF||
'            v_comma := '', ''; '||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
'    END;'||wwv_flow.LF||
''||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- 0. RECUPERATION UTILISATEUR APEX'||wwv_flow.LF||
'    v_user_audit :'||
'= COALESCE(V(''P0_USER''), USER);'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- 1. INITIALISATION'||wwv_flow.LF||
'    IF INSERTING THEN'||wwv_flow.LF||
'        v_action := ''INSERT'';'||wwv_flow.LF||
'        v_record_id := :NEW.ID;'||wwv_flow.LF||
'    ELSIF UPDATING THEN'||wwv_flow.LF||
'        v_action := ''UPDATE'';'||wwv_flow.LF||
'        v_record_id := :NEW.ID;'||wwv_flow.LF||
'    ELSIF DELETING THEN'||wwv_flow.LF||
'        v_action := ''DELETE'';'||wwv_flow.LF||
'        v_record_id := :OLD.ID;'||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- 2. TRAITEMENT DES MODIFICATIONS (UPDATE)'||wwv_flow.LF||
'    IF UPDATING THEN'||wwv_flow.LF||
'    '||
'    -- Champs Textes et Nombres (Attention aux guillemets pour les champs arabes)'||wwv_flow.LF||
'        CHECK_CHANGE(''عدد'', :OLD."عدد", :NEW."عدد");'||wwv_flow.LF||
'        CHECK_CHANGE(''طريقة_ابرام_الصفقة'', :OLD."طريقة_ابرام_الصفقة", :NEW."طريقة_ابرام_الصفقة");'||wwv_flow.LF||
'        CHECK_CHANGE(''نوعية_الطلب'', :OLD."نوعية_الطلب", :NEW."نوعية_الطلب");'||wwv_flow.LF||
'        CHECK_CHANGE(''اللجنة_المختصة'', :OLD."اللجنة_المختصة", :NEW."اللجنة_المختصة");'||wwv_flow.LF||
'    '||
'    CHECK_CHANGE(''المكلف_بالملف'', :OLD."المكلف_بالملف", :NEW."المكلف_بالملف");'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- Champs Dates (Conversion obligatoire en YYYY-MM-DD pour comparaison fiable)'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ورود_CPT_ممضاة'', TO_CHAR(:OLD."تاريخ_ورود_CPT_ممضاة", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ورود_CPT_ممضاة", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ارسال_مقترح'', TO_CHAR(:OLD."تاريخ_ارسال_مقترح_تركيبة_لج'||
'نة_التقييم", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ارسال_مقترح_تركيبة_لجنة_التقييم", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ورود_تعيين'', TO_CHAR(:OLD."تاريخ_ورود_تعيين_تركيبة_لجنة_التقييم", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ورود_تعيين_تركيبة_لجنة_التقييم", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_تقديم_كراسات'', TO_CHAR(:OLD."تاريخ_تقديم_كراسات_الشروط_للمصادقة", ''YYYY-MM-DD''), TO_CHAR(:NEW."ت'||
'اريخ_تقديم_كراسات_الشروط_للمصادقة", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_مصادقة_اللجنة'', TO_CHAR(:OLD."تاريخ_مصادقة_اللجنة_على_كراسات_الشروط", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_مصادقة_اللجنة_على_كراسات_الشروط", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ورود_محضر'', TO_CHAR(:OLD."تاريخ_ورود_محضر_مصادقة_اللجنة_على_كراسات_الشروط", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ورود_محضر_مصادقة_اللجنة_عل'||
'ى_كراسات_الشروط", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ارجاع_كراسات'', TO_CHAR(:OLD."تاريخ_ارجاع_كراسات_الشروط_حسب_المحضر", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ارجاع_كراسات_الشروط_حسب_المحضر", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ورود_محضر_2'', TO_CHAR(:OLD."تاريخ_ورود_محضر_مصادقة_اللجنة_على_كراسات_الشروط2", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ورود_محضر_مصادقة_اللجنة_على_كراسات_الشروط2",'||
' ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''التاريخ_للإعلان'', TO_CHAR(:OLD."التاريخ__للإعلان_عن_المنافسة", ''YYYY-MM-DD''), TO_CHAR(:NEW."التاريخ__للإعلان_عن_المنافسة", ''YYYY-MM-DD''));'||wwv_flow.LF||
'       '||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ارسال_التقرير'', TO_CHAR(:OLD."تاريخ_ارسال_التقرير_للتقييم_الفني", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ارسال_التقرير_للتقييم_الفني", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_امضاء_التقر'||
'ير'', TO_CHAR(:OLD."تاريخ_امضاء_تقرير_تقييم_العروض", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_امضاء_تقرير_تقييم_العروض", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_تقديم_الملف'', TO_CHAR(:OLD."تاريخ_تقديم_الملف_للجنة_الشراءات", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_تقديم_الملف_للجنة_الشراءات", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_لجنة_الصفقات'', TO_CHAR(:OLD."تاريخ__لجنة_الصفقات", ''YYYY-MM-DD''), TO_CH'||
'AR(:NEW."تاريخ__لجنة_الصفقات", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_قرار_اللجنة'', TO_CHAR(:OLD."تاريخ_قرار__لجنة_الصفقات", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_قرار__لجنة_الصفقات", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_نشر_النتائج'', TO_CHAR(:OLD."تاريخ_نشر_نتائج_المنافسة", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_نشر_نتائج_المنافسة", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_تبليغ_الصفقة'', '||
'TO_CHAR(:OLD."تاريخ_تبليغ_الصفقة", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_تبليغ_الصفقة", ''YYYY-MM-DD''));'||wwv_flow.LF||
'        CHECK_CHANGE(''تاريخ_ارجاع_الضمانات'', TO_CHAR(:OLD."تاريخ_ارجاع_الضمانات_الوقتية", ''YYYY-MM-DD''), TO_CHAR(:NEW."تاريخ_ارجاع_الضمانات_الوقتية", ''YYYY-MM-DD''));'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- Si rien n''a changé, on sort sans rien insérer'||wwv_flow.LF||
'        IF v_comma = '''' THEN'||wwv_flow.LF||
'            RETURN; '||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- 3'||
'. CAS INSERTION OU SUPPRESSION (SNAPSHOT PARTIEL)'||wwv_flow.LF||
'    ELSE'||wwv_flow.LF||
'        DECLARE'||wwv_flow.LF||
'            -- Pour simplifier, on prend juste les infos clés pour identifier la ligne'||wwv_flow.LF||
'            -- Vous pouvez ajouter plus de champs si nécessaire'||wwv_flow.LF||
'        BEGIN'||wwv_flow.LF||
'             IF INSERTING THEN'||wwv_flow.LF||
'                 v_new_clob := ''{'' || '||wwv_flow.LF||
'                    ''"ID": "'' || :NEW.ID || ''", '' ||'||wwv_flow.LF||
'                    ''"عدد": "'' || SAF'||
'E_TXT(:NEW."عدد") || ''", '';'||wwv_flow.LF||
'             ELSIF DELETING THEN'||wwv_flow.LF||
'                 v_old_clob := ''{'' || '||wwv_flow.LF||
'                    ''"ID": "'' || :OLD.ID || ''", '' ||'||wwv_flow.LF||
'                    ''"عدد": "'' || SAFE_TXT(:OLD."عدد") || ''", '';'||wwv_flow.LF||
'             END IF;'||wwv_flow.LF||
'        END;'||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Fermeture JSON'||wwv_flow.LF||
'    v_old_clob := v_old_clob || ''}'';'||wwv_flow.LF||
'    v_new_clob := v_new_clob || ''}'';'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- 4. INSERTION BASE DE DONNEES'||wwv_flow.LF||
'  '||
'  INSERT INTO AUDIT_LOG ('||wwv_flow.LF||
'        TABLE_NAME, ACTION_TYPE, RECORD_ID, OLD_VALUE, NEW_VALUE, CHANGED_BY'||wwv_flow.LF||
'    ) VALUES ('||wwv_flow.LF||
'        ''SP'', v_action, v_record_id, v_old_clob, v_new_clob, v_user_audit'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'END;'||wwv_flow.LF||
'/'||wwv_flow.LF||
'ALTER TRIGGER "TRG_AUDIT_SP" ENABLE;'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202512031539','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'STEG2');
end;
