begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 13838446659273168
 ,p_command => 
'  CREATE TABLE "SP2" '||wwv_flow.LF||
'   (	"ID" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 , '||wwv_flow.LF||
'	"عدد" VARCHAR2(50), '||wwv_flow.LF||
'	"موضوع_الصفقة" VARCHAR2(4000), '||wwv_flow.LF||
'	"EXP__INV" VARCHAR2(50), '||wwv_flow.LF||
'	"طريقة_ابرام_الصفقة" VARCHAR2(255), '||wwv_flow.LF||
