'جنة_التقييم" DATE, '||wwv_flow.LF||
'	"تاريخ_ورود_تعيين_تركيبة_لجنة_التقييم" DATE, '||wwv_flow.LF||
'	"تاريخ_تقديم_كراسات_الشروط_للمصادقة" DATE, '||wwv_flow.LF||
'	"تاريخ_مصادقة_اللجنة_على_كراسات_الشروط" DATE, '||wwv_flow.LF||
'	"تاريخ_ورود_محضر_مصادقة_اللجنة_على_كراسات_الشروط" DATE, '||wwv_flow.LF||
'	"تاريخ_ارجاع_كراسات_الشروط_حسب_المحضر" DATE, '||wwv_flow.LF||
'	"تاريخ_ورود_محضر_مصادقة_اللجنة_على_كراسات_الشروط2" DATE, '||wwv_flow.LF||
'	"التاريخ__للإعلان_عن_المنافسة" DATE, '||wwv_flow.LF||
'	"تاريخ_ارسال_التقرير_للتقييم_الفني" '||
'DATE, '||wwv_flow.LF||
'	"تاريخ_امضاء_تقرير_تقييم_العروض" DATE, '||wwv_flow.LF||
'	"تاريخ_تقديم_الملف_للجنة_الشراءات" DATE, '||wwv_flow.LF||
'	"تاريخ__لجنة_الصفقات" DATE, '||wwv_flow.LF||
'	"تاريخ_قرار__لجنة_الصفقات" DATE, '||wwv_flow.LF||
