begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 16260837240042364
 ,p_command => 
'CREATE TABLE SP_SECURE ('||wwv_flow.LF||
'    ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,'||wwv_flow.LF||
'    MATRICULE VARCHAR2(50) UNIQUE NOT NULL,'||wwv_flow.LF||
'    NOM VARCHAR2(100) NOT NULL,'||wwv_flow.LF||
'    MDP_HASH VARCHAR2(255) NOT NULL,'||wwv_flow.LF||
'    GROUPE VARCHAR2(50),'||wwv_flow.LF||
'    DATE_CREATION DATE DEFAULT SYSDATE,'||wwv_flow.LF||
'    DATE_MAJ_MDP DATE DEFAULT SYSDATE,'||wwv_flow.LF||
'    DERNIER_CONNEXION DATE,'||wwv_flow.LF||
'    TENTATIVES_ECHOUEES NUMBER DEFAULT 0,'||wwv_flow.LF||
'    COMPTE_VERROUILL'||
'E VARCHAR2(1) DEFAULT ''N'','||wwv_flow.LF||
'    CONSTRAINT chk_compte_verrouille CHECK (COMPTE_VERROUILLE IN (''Y'', ''N''))'||wwv_flow.LF||
');'||wwv_flow.LF||
''||wwv_flow.LF||
'-- Index pour optimiser les recherches'||wwv_flow.LF||
'CREATE INDEX idx_sp_secure_matricule ON SP_SECURE(MATRICULE);'||wwv_flow.LF||
'CREATE INDEX idx_sp_secure_nom ON SP_SECURE(NOM);'||wwv_flow.LF||
''||wwv_flow.LF||
'-- 2.2 Fonction de hachage utilisant APEX_UTIL'||wwv_flow.LF||
'CREATE OR REPLACE FUNCTION hash_password_apex('||wwv_flow.LF||
'    p_password VARCHAR2,'||wwv_flow.LF||
'    p_username VARCHA'||
'R2'||wwv_flow.LF||
') RETURN VARCHAR2 IS'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- Utilise le hachage APEX intégré (SHA-512)'||wwv_flow.LF||
'    RETURN APEX_UTIL.GET_HASH('||wwv_flow.LF||
'        APEX_T_VARCHAR2(p_username, p_password)'||wwv_flow.LF||
'    );'||wwv_flow.LF||
'END hash_password_apex;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'-- 2.3 Fonction alternative avec DBMS_OBFUSCATION_TOOLKIT (ancienne méthode)'||wwv_flow.LF||
'CREATE OR REPLACE FUNCTION hash_password_legacy('||wwv_flow.LF||
'    p_password VARCHAR2,'||wwv_flow.LF||
'    p_salt VARCHAR2'||wwv_flow.LF||
') RETURN VARCHAR2 IS'||wwv_flow.LF||
'    l_raw_input '||
'RAW(2000);'||wwv_flow.LF||
'    l_raw_hash RAW(2000);'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- Convertir en RAW'||wwv_flow.LF||
'    l_raw_input := UTL_RAW.CAST_TO_RAW(p_password || p_salt);'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Hacher avec MD5 (moins sécurisé mais disponible partout)'||wwv_flow.LF||
'    l_raw_hash := DBMS_OBFUSCATION_TOOLKIT.MD5('||wwv_flow.LF||
'        input => l_raw_input'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    RETURN RAWTOHEX(l_raw_hash);'||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN OTHERS THEN'||wwv_flow.LF||
'        -- Si DBMS_OBFUSCATION_TOOLKIT n''est pas disponib'||
'le non plus'||wwv_flow.LF||
'        -- Utiliser un hash simple (pour développement uniquement)'||wwv_flow.LF||
'        RETURN RAWTOHEX(UTL_RAW.CAST_TO_RAW(p_password || p_salt));'||wwv_flow.LF||
'END hash_password_legacy;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'-- 2.4 Fonction de génération de salt'||wwv_flow.LF||
'CREATE OR REPLACE FUNCTION generate_salt_apex RETURN VARCHAR2 IS'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    -- Utilise DBMS_RANDOM qui est généralement disponible'||wwv_flow.LF||
'    RETURN RAWTOHEX(DBMS_RANDOM.RANDOM) || RAWTOHEX(DBMS'||
'_RANDOM.RANDOM);'||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN OTHERS THEN'||wwv_flow.LF||
'        -- Fallback si DBMS_RANDOM n''est pas accessible'||wwv_flow.LF||
'        RETURN TO_CHAR(SYSTIMESTAMP, ''YYYYMMDDHH24MISSFF6'') || '||wwv_flow.LF||
'               TO_CHAR(DBMS_UTILITY.GET_TIME);'||wwv_flow.LF||
'END generate_salt_apex;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'-- 2.5 Package de gestion des utilisateurs sécurisé'||wwv_flow.LF||
'CREATE OR REPLACE PACKAGE PKG_USER_SECURITY AS'||wwv_flow.LF||
'    -- Créer ou mettre à jour un utilisateur'||wwv_flow.LF||
'    PROCEDURE '||
'set_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_nom VARCHAR2,'||wwv_flow.LF||
'        p_password VARCHAR2,'||wwv_flow.LF||
'        p_groupe VARCHAR2 DEFAULT NULL'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Authentifier un utilisateur'||wwv_flow.LF||
'    FUNCTION authenticate_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_password VARCHAR2'||wwv_flow.LF||
'    ) RETURN BOOLEAN;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Vérifier si un compte est verrouillé'||wwv_flow.LF||
'    FUNCTION is_account_locked(p_matricule VARCHAR2) RETURN BOOLEAN;'||
''||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Déverrouiller un compte'||wwv_flow.LF||
'    PROCEDURE unlock_account(p_matricule VARCHAR2);'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Réinitialiser le mot de passe'||wwv_flow.LF||
'    PROCEDURE reset_password('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_new_password VARCHAR2'||wwv_flow.LF||
'    );'||wwv_flow.LF||
'END PKG_USER_SECURITY;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202512031604','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'STEG2');
end;
/
