 ,p_command => 
' 2.5 Package de gestion des utilisateurs sécurisé'||wwv_flow.LF||
'CREATE OR REPLACE PACKAGE PKG_USER_SECURITY AS'||wwv_flow.LF||
'    -- Créer ou mettre à jour un utilisateur'||wwv_flow.LF||
'    PROCEDURE set_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_nom VARCHAR2,'||wwv_flow.LF||
'        p_password VARCHAR2,'||wwv_flow.LF||
'        p_groupe VARCHAR2 DEFAULT NULL'||wwv_flow.LF||
'    );'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Authentifier un utilisateur'||wwv_flow.LF||
'    FUNCTION authenticate_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'       '||
' p_password VARCHAR2'||wwv_flow.LF||
'    ) RETURN BOOLEAN;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Vérifier si un compte est verrouillé'||wwv_flow.LF||
'    FUNCTION is_account_locked(p_matricule VARCHAR2) RETURN BOOLEAN;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Déverrouiller un compte'||wwv_flow.LF||
'    PROCEDURE unlock_account(p_matricule VARCHAR2);'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Réinitialiser le mot de passe'||wwv_flow.LF||
'    PROCEDURE reset_password('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_new_password VARCHAR2'||wwv_flow.LF||
'    );'||wwv_flow.LF||
'END PKG_USER_SECURITY;'||
''||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'CREATE OR REPLACE PACKAGE BODY PKG_USER_SECURITY AS'||wwv_flow.LF||
''||wwv_flow.LF||
'    c_max_attempts CONSTANT NUMBER := 3;'||wwv_flow.LF||
''||wwv_flow.LF||
'    PROCEDURE set_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_nom VARCHAR2,'||wwv_flow.LF||
'        p_password VARCHAR2,'||wwv_flow.LF||
'        p_groupe VARCHAR2 DEFAULT NULL'||wwv_flow.LF||
'    ) IS'||wwv_flow.LF||
'        l_hash VARCHAR2(255);'||wwv_flow.LF||
'        l_count NUMBER;'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        -- Hasher le mot de passe avec APEX_UTIL'||wwv_flow.LF||
'        l_hash := hash_password_a'||
'pex(p_password, p_matricule);'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- Vérifier si l''utilisateur existe'||wwv_flow.LF||
'        SELECT COUNT(*) INTO l_count'||wwv_flow.LF||
'        FROM SP_SECURE'||wwv_flow.LF||
'        WHERE MATRICULE = p_matricule;'||wwv_flow.LF||
''||wwv_flow.LF||
'        IF l_count = 0 THEN'||wwv_flow.LF||
'            -- Créer nouveau'||wwv_flow.LF||
'            INSERT INTO SP_SECURE (MATRICULE, NOM, MDP_HASH, GROUPE, DATE_MAJ_MDP)'||wwv_flow.LF||
'            VALUES (p_matricule, p_nom, l_hash, p_groupe, SYSDATE);'||wwv_flow.LF||
'        ELSE'||wwv_flow.LF||
'    '||
'        -- Mettre à jour'||wwv_flow.LF||
'            UPDATE SP_SECURE'||wwv_flow.LF||
'            SET NOM = p_nom,'||wwv_flow.LF||
'                MDP_HASH = l_hash,'||wwv_flow.LF||
'                GROUPE = NVL(p_groupe, GROUPE),'||wwv_flow.LF||
'                DATE_MAJ_MDP = SYSDATE,'||wwv_flow.LF||
'                TENTATIVES_ECHOUEES = 0,'||wwv_flow.LF||
'                COMPTE_VERROUILLE = ''N'''||wwv_flow.LF||
'            WHERE MATRICULE = p_matricule;'||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'        COMMIT;'||wwv_flow.LF||
'    END set_user;'||wwv_flow.LF||
''||wwv_flow.LF||
'    FUNCTION authe'||
'nticate_user('||wwv_flow.LF||
'        p_matricule VARCHAR2,'||wwv_flow.LF||
'        p_password VARCHAR2'||wwv_flow.LF||
'    ) RETURN BOOLEAN IS'||wwv_flow.LF||
'        l_stored_hash VARCHAR2(255);'||wwv_flow.LF||
'        l_computed_hash VARCHAR2(255);'||wwv_flow.LF||
'        l_locked VARCHAR2(1);'||wwv_flow.LF||
'        l_attempts NUMBER;'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
'        -- Récupérer les infos de l''utilisateur'||wwv_flow.LF||
'        BEGIN'||wwv_flow.LF||
'            SELECT MDP_HASH, COMPTE_VERROUILLE, TENTATIVES_ECHOUEES'||wwv_flow.LF||
'            INTO l_stored_hash,'||
' l_locked, l_attempts'||wwv_flow.LF||
'            FROM SP_SECURE'||wwv_flow.LF||
'            WHERE MATRICULE = p_matricule;'||wwv_flow.LF||
'        EXCEPTION'||wwv_flow.LF||
'            WHEN NO_DATA_FOUND THEN'||wwv_flow.LF||
'                RETURN FALSE;'||wwv_flow.LF||
'        END;'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- Vérifier si le compte est verrouillé'||wwv_flow.LF||
'        IF l_locked = ''Y'' THEN'||wwv_flow.LF||
'            RAISE_APPLICATION_ERROR(-20001, '||wwv_flow.LF||
'                ''Compte verrouillé. Contactez l''''administrateur.'');'||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
' '||
'       -- Calculer le hash du mot de passe fourni'||wwv_flow.LF||
'        l_computed_hash := hash_password_apex(p_password, p_matricule);'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- Comparer les hash'||wwv_flow.LF||
'        IF l_stored_hash = l_computed_hash THEN'||wwv_flow.LF||
'            -- Authentification réussie'||wwv_flow.LF||
'            UPDATE SP_SECURE'||wwv_flow.LF||
'            SET TENTATIVES_ECHOUEES = 0,'||wwv_flow.LF||
'                DERNIER_CONNEXION = SYSDATE'||wwv_flow.LF||
'            WHERE MATRICULE = p_matricule;'||wwv_flow.LF||
'   '||
'         COMMIT;'||wwv_flow.LF||
'            RETURN TRUE;'||wwv_flow.LF||
'        ELSE'||wwv_flow.LF||
'            -- Échec d''authentification'||wwv_flow.LF||
'            l_attempts := l_attempts + 1;'||wwv_flow.LF||
''||wwv_flow.LF||
'            UPDATE SP_SECURE'||wwv_flow.LF||
'            SET TENTATIVES_ECHOUEES = l_attempts,'||wwv_flow.LF||
'                COMPTE_VERROUILLE = CASE '||wwv_flow.LF||
'                    WHEN l_attempts >= c_max_attempts THEN ''Y'' '||wwv_flow.LF||
'                    ELSE ''N'' '||wwv_flow.LF||
'                END'||wwv_flow.LF||
'            WHERE MATRICULE'||
' = p_matricule;'||wwv_flow.LF||
'            COMMIT;'||wwv_flow.LF||
''||wwv_flow.LF||
'            IF l_attempts >= c_max_attempts THEN'||wwv_flow.LF||
'                RAISE_APPLICATION_ERROR(-20002, '||wwv_flow.LF||
'                    ''Compte verrouillé après '' || c_max_attempts || '' tentatives échouées.'');'||wwv_flow.LF||
'            END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'            RETURN FALSE;'||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
'    END authenticate_user;'||wwv_flow.LF||
''||wwv_flow.LF||
'    FUNCTION is_account_locked(p_matricule VARCHAR2) RETURN BOOLEAN IS'||wwv_flow.LF||
'        l'||
'_locked VARCHAR2(1);'||wwv_flow.LF||
'    BEGIN'||wwv_flow.LF||
