''||wwv_flow.LF||
'        IF SQL%ROWCOUNT = 0 THEN'||wwv_flow.LF||
'            RAISE_APPLICATION_ERROR(-20003, ''Utilisateur non trouvé.'');'||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'        COMMIT;'||wwv_flow.LF||
'    END reset_password;'||wwv_flow.LF||
''||wwv_flow.LF||
'END PKG_USER_SECURITY;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''||wwv_flow.LF||
'-- 2.6 Migration des utilisateurs depuis l''ancienne table SP'||wwv_flow.LF||
'CREATE OR REPLACE PROC'||
