begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 18100360201206126
 ,p_command => 
'CREATE OR REPLACE PROCEDURE CLEANUP_EXPIRED_REMINDERS AS'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    DELETE FROM USER_NOTES WHERE '||wwv_flow.LF||
'        -- التنبيهات التي فات موعد التنبيه الفعلي'||wwv_flow.LF||
'        REMINDER_DATETIME - (NVL(PRE_REMINDER_MINS,0)/1440) < SYSDATE - 1  -- يوم كامل بعد التنبيه'||wwv_flow.LF||
'        AND IS_SENT = ''Y'';  -- تم إرسالها فقط'||wwv_flow.LF||
'        '||wwv_flow.LF||
'    COMMIT;'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    -- تسجيل العملية (اختياري)'||wwv_flow.LF||
'    INSERT INTO USER_NOTES_LOG (LOG_DATE, ACTION, R'||
'OWS_DELETED)'||wwv_flow.LF||
'    VALUES (SYSDATE, ''CLEANUP_EXPIRED'', SQL%ROWCOUNT);'||wwv_flow.LF||
'    '||wwv_flow.LF||
'    COMMIT;'||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN OTHERS THEN'||wwv_flow.LF||
'        ROLLBACK;'||wwv_flow.LF||
'        RAISE;'||wwv_flow.LF||
'END;'||wwv_flow.LF||
'/'||wwv_flow.LF||
''
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202512221536','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
