begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 31219289681532501
 ,p_command => 
'CREATE OR REPLACE PROCEDURE ctrl_cc_rappels_custom ('||wwv_flow.LF||
'  p_app_id IN NUMBER DEFAULT 105  -- Remplacez 100 par votre APP_ID'||wwv_flow.LF||
') AS'||wwv_flow.LF||
'  CURSOR c_cc IS'||wwv_flow.LF||
'    SELECT DISTINCT REF_AO'||wwv_flow.LF||
'    FROM cc'||wwv_flow.LF||
'    WHERE status = 5'||wwv_flow.LF||
'    AND NOT EXISTS ('||wwv_flow.LF||
'      SELECT 1 FROM custom_notifications '||wwv_flow.LF||
'      WHERE ref_ao = cc.REF_AO'||wwv_flow.LF||
'    );'||wwv_flow.LF||
'    '||wwv_flow.LF||
'  l_users SYS.DBMS_SQL.VARCHAR2_TABLE;'||wwv_flow.LF||
'  l_user VARCHAR2(255);'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'  SELECT username BULK'||
' COLLECT INTO l_users'||wwv_flow.LF||
'  FROM apex_acl_user_roles u'||wwv_flow.LF||
'  WHERE EXISTS ('||wwv_flow.LF||
'    SELECT 1 FROM apex_acl_roles r '||wwv_flow.LF||
'    WHERE r.application_id = p_app_id'||wwv_flow.LF||
'    AND r.static_id IN (''CONTRIBUTOR'', ''ADMINISTRATOR'')'||wwv_flow.LF||
'    AND u.role_static_id = r.static_id'||wwv_flow.LF||
'    AND u.application_id = r.application_id'||wwv_flow.LF||
'  );'||wwv_flow.LF||
'  '||wwv_flow.LF||
'  FOR rec IN c_cc LOOP'||wwv_flow.LF||
'    FOR i IN 1..l_users.COUNT LOOP'||wwv_flow.LF||
'      l_user := l_users(i);'||wwv_flow.LF||
'      '||wwv_flow.LF||
'      INSERT INTO '||
'custom_notifications (ref_ao, username, title, body, app_id)'||wwv_flow.LF||
'      VALUES (rec.REF_AO, l_user, ''Rappel CC Status 5'', '||wwv_flow.LF||
'              ''Vérifiez la référence CC '' || rec.REF_AO || '' (status=5).'','||wwv_flow.LF||
'              p_app_id);'||wwv_flow.LF||
'    END LOOP;'||wwv_flow.LF||
'  END LOOP;'||wwv_flow.LF||
'  '||wwv_flow.LF||
'  COMMIT;'||wwv_flow.LF||
'END;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604011541','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
