begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 32678096495739934
 ,p_command => 
'SELECT '||wwv_flow.LF||
' /*   CASE ETAT'||wwv_flow.LF||
'        WHEN ''1'' THEN ''En cours de Préparation'''||wwv_flow.LF||
'        WHEN ''2'' THEN ''Appel d''''Offres en cour'''||wwv_flow.LF||
'        WHEN ''3'' THEN ''En cour d''''Évaluation'''||wwv_flow.LF||
'        WHEN ''4'' THEN ''Traité en attente de classement'''||wwv_flow.LF||
'        when ''5'' then ''Infructueux'''||wwv_flow.LF||
'        when ''6'' then ''Fructueux'''||wwv_flow.LF||
'        ELSE NVL(ETAT, ''Non défini'')'||wwv_flow.LF||
'    END AS LABEL,*/'||wwv_flow.LF||
' CASE'||wwv_flow.LF||
'      WHEN DATE_FIN_DU_MARCHÉ IS NOT NULL '||wwv_flow.LF||
'  '||
'       AND DATE_FIN_DU_MARCHÉ < SYSDATE'||wwv_flow.LF||
'    THEN ''Clôturé''   '||wwv_flow.LF||
'     WHEN DATE_DE_MISE_VIGUEUR <=  SYSDATE'||wwv_flow.LF||
'         AND (DATE_FIN_DU_MARCHÉ IS NULL '||wwv_flow.LF||
'              OR DATE_FIN_DU_MARCHÉ <= SYSDATE)'||wwv_flow.LF||
'               THEN ''En exécution'''||wwv_flow.LF||
'    WHEN DATE_GARANTIE_FINALE IS NOT NULL THEN ''Cautionnement Définitif reçue'''||wwv_flow.LF||
'    WHEN DATE_RETOUR_ENREGISTRE IS NOT NULL THEN ''Contrat enregistré'''||wwv_flow.LF||
'    WHEN DATE_ENVOI_C'||
'LIENT_ENREGISTREMENT IS NOT NULL THEN ''Enregistrement en cours'''||wwv_flow.LF||
'    WHEN DATE_RETOUR_ADMIN_SIGNE IS NOT NULL THEN ''Signé par administration'''||wwv_flow.LF||
'    WHEN DATE_ENVOI_ADMIN_SIGNATURE IS NOT NULL THEN ''En attente signature administration'''||wwv_flow.LF||
'    WHEN DATE_RETOUR_CLIENT_SIGNE IS NOT NULL THEN ''Signé par titulaire'''||wwv_flow.LF||
'    WHEN DATE_ENVOI_CLIENT_SIGNATURE IS NOT NULL THEN ''En attente signature titulaire'''||wwv_flow.LF||
'    WHEN'||
' DATE_AVIS_JURIDIQUE IS NOT NULL THEN ''Avis juridique reçu'''||wwv_flow.LF||
'    WHEN DATE_LIVRAISON_JURIDIQUE IS NOT NULL THEN ''En cours avis juridique'''||wwv_flow.LF||
''||wwv_flow.LF||
'   '||wwv_flow.LF||
'    '||wwv_flow.LF||
'    ELSE ''Nouveau / Non traité'''||wwv_flow.LF||
'END AS LABEL,'||wwv_flow.LF||
''||wwv_flow.LF||
''||wwv_flow.LF||
'    COUNT(*) AS VALEUR2'||wwv_flow.LF||
'FROM CONTRATS CONTRATS '||wwv_flow.LF||
'GROUP BY LABEL'||wwv_flow.LF||
'ORDER BY LABEL'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604131324','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
