begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 34014203310252784
 ,p_command => 
'CREATE OR REPLACE FUNCTION f_authenticate_user ('||wwv_flow.LF||
'    p_username IN VARCHAR2,'||wwv_flow.LF||
'    p_password IN VARCHAR2'||wwv_flow.LF||
') RETURN BOOLEAN IS'||wwv_flow.LF||
'    v_count NUMBER;'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    SELECT COUNT(*)'||wwv_flow.LF||
'    INTO v_count'||wwv_flow.LF||
'    FROM T_USER'||wwv_flow.LF||
'    WHERE MATRICULE = TO_NUMBER(p_username)'||wwv_flow.LF||
'      AND MDP = p_password;  -- ⚠️ Idéalement, utilisez un hash (ex: SHA256)'||wwv_flow.LF||
''||wwv_flow.LF||
'    RETURN v_count > 0;'||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN OTHERS THEN'||wwv_flow.LF||
'        RETURN FALSE'||
';'||wwv_flow.LF||
'END f_authenticate_user;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604170859','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
