begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 31179819642110801
 ,p_command => 
'CREATE TABLE SUIVI_CONTRATS ('||wwv_flow.LF||
'    ID_CONTRAT          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,'||wwv_flow.LF||
'    NUMERO_CONTRAT      VARCHAR2(50),'||wwv_flow.LF||
'    LIBELLE             VARCHAR2(200),'||wwv_flow.LF||
'    DATE_LIVRAISON_JURIDIQUE DATE,'||wwv_flow.LF||
'    DATE_AVIS_JURIDIQUE DATE,'||wwv_flow.LF||
'    DATE_ENVOI_CLIENT_SIGNATURE DATE,'||wwv_flow.LF||
'    DATE_RETOUR_CLIENT_SIGNE DATE,'||wwv_flow.LF||
'    DATE_ENVOI_ADMIN_SIGNATURE DATE,'||wwv_flow.LF||
'    DATE_RETOUR_ADMIN_SIGNE DATE,'||wwv_flow.LF||
'    DAT'||
'E_ENVOI_CLIENT_ENREGISTREMENT DATE,'||wwv_flow.LF||
'    DATE_RETOUR_ENREGISTRE DATE,'||wwv_flow.LF||
'    DATE_GARANTIE_FINALE DATE,'||wwv_flow.LF||
'    RESPONSABLE_MO      VARCHAR2(100)'||wwv_flow.LF||
');'||wwv_flow.LF||
''||wwv_flow.LF||
'COMMENT ON TABLE SUIVI_CONTRATS IS ''Tableau de suivi des contrats et commandes'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.NUMERO_CONTRAT IS ''Numéro du contrat/commande'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.LIBELLE IS ''Libellé contrat/commande'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_'||
'CONTRATS.DATE_LIVRAISON_JURIDIQUE IS ''Date soumission affaire service juridique'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_AVIS_JURIDIQUE IS ''Date réception avis juridique'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_ENVOI_CLIENT_SIGNATURE IS ''Date envoi contrat au client pour signature'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_RETOUR_CLIENT_SIGNE IS ''Date retour contrat signé par client'';'||wwv_flow.LF||
'COMMENT ON COLUMN'||
' SUIVI_CONTRATS.DATE_ENVOI_ADMIN_SIGNATURE IS ''Date envoi contrat à l''''administration'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_RETOUR_ADMIN_SIGNE IS ''Date retour contrat signé par administration'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_ENVOI_CLIENT_ENREGISTREMENT IS ''Date envoi contrat au client pour enregistrement'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_RETOUR_ENREGISTRE IS ''Date retour contrat enr'||
'egistré'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.DATE_GARANTIE_FINALE IS ''Date réception garantie finale'';'||wwv_flow.LF||
'COMMENT ON COLUMN SUIVI_CONTRATS.RESPONSABLE_MO IS ''Responsable du dossier'';'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604011431','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
