begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 34015170403291507
 ,p_command => 
'CREATE OR REPLACE PROCEDURE p_post_auth AS'||wwv_flow.LF||
'    v_nom    T_USER.NOM%TYPE;'||wwv_flow.LF||
'    v_groupe T_USER.GROUPE%TYPE;'||wwv_flow.LF||
'    v_id     T_USER.ID_1%TYPE;'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    SELECT ID_1, NOM, GROUPE'||wwv_flow.LF||
'    INTO v_id, v_nom, v_groupe'||wwv_flow.LF||
'    FROM T_USER'||wwv_flow.LF||
'    WHERE MATRICULE = TO_NUMBER(V(''APP_USER''));'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- Stocker dans des items d''application'||wwv_flow.LF||
'    APEX_UTIL.SET_SESSION_STATE(''APP_NOM'',    v_nom);'||wwv_flow.LF||
'    APEX_UTIL.SET_SESSION_STATE(''A'||
'PP_GROUPE'', v_groupe);'||wwv_flow.LF||
'    APEX_UTIL.SET_SESSION_STATE(''APP_ID'',     TO_CHAR(v_id));'||wwv_flow.LF||
''||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN NO_DATA_FOUND THEN NULL;'||wwv_flow.LF||
'END p_post_auth;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604170906','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
