'        -- Gr'||
'oupe inconnu : retour login avec message d''erreur'||wwv_flow.LF||
'        APEX_UTIL.REDIRECT_URL('||wwv_flow.LF||
'            APEX_PAGE.GET_URL(p_page => 9999)'||wwv_flow.LF||
'        );'||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN NO_DATA_FOUND THEN'||wwv_flow.LF||
'        APEX_UTIL.REDIRECT_URL('||wwv_flow.LF||
'            APEX_PAGE.GET_URL(p_page => 9999)'||wwv_flow.LF||
