begin
  wwv_imp_workspace.create_sw_sql_cmds (
    p_id => 36860039704214506
 ,p_command => 
'CREATE OR REPLACE TRIGGER BIU_HEUR_SPP'||wwv_flow.LF||
'BEFORE INSERT OR UPDATE'||wwv_flow.LF||
'ON HEUR_SPP'||wwv_flow.LF||
'FOR EACH ROW'||wwv_flow.LF||
'DECLARE'||wwv_flow.LF||
''||wwv_flow.LF||
'    v_minutes NUMBER;'||wwv_flow.LF||
''||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
'    -- CALCUL NBR_H'||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
''||wwv_flow.LF||
'    IF :NEW.DEBUT IS NOT NULL'||wwv_flow.LF||
'    AND :NEW.FIN IS NOT NULL THEN'||wwv_flow.LF||
''||wwv_flow.LF||
'        v_minutes :='||wwv_flow.LF||
'            ('||wwv_flow.LF||
'                (:NEW.FIN - :NEW.DEBUT)'||wwv_flow.LF||
'                * 24'||wwv_flow.LF||
'                * 60'||wwv_flow.LF||
'    '||
'        );'||wwv_flow.LF||
''||wwv_flow.LF||
'        -- passage minuit'||wwv_flow.LF||
'        IF v_minutes < 0 THEN'||wwv_flow.LF||
'            v_minutes := v_minutes + (24 * 60);'||wwv_flow.LF||
'        END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'        :NEW.NBR_H :='||wwv_flow.LF||
'            CEIL(v_minutes / 60);'||wwv_flow.LF||
''||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
'    -- CALCUL PERIODE RH'||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
''||wwv_flow.LF||
'    IF EXTRACT(DAY FROM :NEW.DATE_J) >= 22 THEN'||wwv_flow.LF||
''||wwv_flow.LF||
'        :NEW.PERIODE_RH :='||wwv_flow.LF||
'            TO_CHAR('||wwv_flow.LF||
'        '||
'        ADD_MONTHS(:NEW.DATE_J,1),'||wwv_flow.LF||
'                ''MM/YYYY'''||wwv_flow.LF||
'            );'||wwv_flow.LF||
''||wwv_flow.LF||
'    ELSE'||wwv_flow.LF||
''||wwv_flow.LF||
'        :NEW.PERIODE_RH :='||wwv_flow.LF||
'            TO_CHAR('||wwv_flow.LF||
'                :NEW.DATE_J,'||wwv_flow.LF||
'                ''MM/YYYY'''||wwv_flow.LF||
'            );'||wwv_flow.LF||
''||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'END;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202605221409','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
/
