 ,p_command => 
'CREATE OR REPLACE TRIGGER BIU_HEUR_SPP'||wwv_flow.LF||
'BEFORE INSERT OR UPDATE'||wwv_flow.LF||
'ON HEUR_SPP'||wwv_flow.LF||
'FOR EACH ROW'||wwv_flow.LF||
'DECLARE'||wwv_flow.LF||
''||wwv_flow.LF||
'    v_minutes NUMBER;'||wwv_flow.LF||
''||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
'    -- CALCUL HEURES'||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
''||wwv_flow.LF||
'    IF :NEW.DEBUT IS NOT NULL'||wwv_flow.LF||
'    AND :NEW.FIN IS NOT NULL THEN'||wwv_flow.LF||
''||wwv_flow.LF||
