'            CEIL(v_minutes / 60);'||wwv_flow.LF||
''||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
'    -- PERIODE RH 22 -> 21'||wwv_flow.LF||
'    -- ========================='||wwv_flow.LF||
''||wwv_flow.LF||
'    IF EXTRACT(DAY FROM :NEW.DATE_J) >= 22 THEN'||wwv_flow.LF||
''||wwv_flow.LF||
'        :NEW.PERIODE_RH :='||wwv_flow.LF||
