 ,p_command => 
'CREATE OR REPLACE FUNCTION f_login_redirect RETURN VARCHAR2 AS'||wwv_flow.LF||
'    v_groupe T_USER.GROUPE%TYPE;'||wwv_flow.LF||
'BEGIN'||wwv_flow.LF||
'    SELECT GROUPE'||wwv_flow.LF||
'    INTO v_groupe'||wwv_flow.LF||
'    FROM T_USER'||wwv_flow.LF||
'    WHERE MATRICULE = TO_NUMBER(V(''APP_USER''));'||wwv_flow.LF||
''||wwv_flow.LF||
'    IF v_groupe IN (''ADMINISTRATOR'', ''CONTRIBUTOR'') THEN'||wwv_flow.LF||
'        RETURN APEX_PAGE.GET_URL(p_page => 44);'||wwv_flow.LF||
'    ELSIF v_groupe = ''READER'' THEN'||wwv_flow.LF||
'        RETURN APEX_PAGE.GET_URL(p_page => 1);'||wwv_flow.LF||
'    ELSE'||wwv_flow.LF||
' '||
'       RETURN APEX_PAGE.GET_URL(p_page => 9999);'||wwv_flow.LF||
'    END IF;'||wwv_flow.LF||
''||wwv_flow.LF||
'EXCEPTION'||wwv_flow.LF||
'    WHEN NO_DATA_FOUND THEN'||wwv_flow.LF||
'        RETURN APEX_PAGE.GET_URL(p_page => 9999);'||wwv_flow.LF||
'END f_login_redirect;'||wwv_flow.LF||
'/'
    ,p_created_by => 'CHIRAZ'
    ,p_created_on => to_date('202604171120','YYYYMMDDHH24MI')
    ,p_parsed_schema => 'WKSP_GCT');
end;
